package vn.rtr.aeris.journey33;
import java.nio.file.*;import java.nio.channels.*;import java.nio.ByteBuffer;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.io.*;import java.util.*;
/** Immutable bytes/revisions + atomic head. No restoration of runtime authority. */
public final class DraftStore {
 public static final int MAX_BODY=262144,MAX_RECORDS=512;public static final long MAX_TOTAL=67108864,RESERVE=16777216;
 private final Path root;public interface Fault{void at(String point)throws IOException;}private final Fault fault;
 public static final class Snapshot {public final long revision;public final String token,previous,sha;public final byte[] bytes;Snapshot(long n,String t,String p,String s,byte[] b){revision=n;token=t;previous=p;sha=s;bytes=b.clone();}}
 public DraftStore(Path p)throws IOException{this(p,x->{});}public DraftStore(Path p,Fault f)throws IOException{root=p.toAbsolutePath().normalize();Path at=root;while(at!=null){if(Files.isSymbolicLink(at))throw new IOException("Symlink ancestor");at=at.getParent();}Files.createDirectories(root);fault=f;}
 public static String hash(byte[] b){try{StringBuilder s=new StringBuilder();for(byte x:MessageDigest.getInstance("SHA-256").digest(b))s.append(String.format(Locale.ROOT,"%02x",x&255));return s.toString();}catch(Exception e){throw new IllegalStateException(e);}}
 private Path safe(String name)throws IOException{Path p=root.resolve(name);if(Files.isSymbolicLink(p))throw new IOException("Symlink store entry");return p;}
 private byte[] read(Path p,int limit)throws IOException{if(!Files.isRegularFile(p,LinkOption.NOFOLLOW_LINKS)||Files.size(p)>limit)throw new IOException("File type/bound");try(FileChannel c=FileChannel.open(p,StandardOpenOption.READ,LinkOption.NOFOLLOW_LINKS)){ByteArrayOutputStream out=new ByteArrayOutputStream();ByteBuffer b=ByteBuffer.allocate(4096);while(c.read(b)>0){b.flip();out.write(b.array(),0,b.remaining());if(out.size()>limit)throw new IOException("Growing file");b.clear();}return out.toByteArray();}}
 private void write(Path p,byte[] b)throws IOException{try(FileChannel c=FileChannel.open(p,StandardOpenOption.CREATE_NEW,StandardOpenOption.WRITE,LinkOption.NOFOLLOW_LINKS)){ByteBuffer x=ByteBuffer.wrap(b);while(x.hasRemaining())if(c.write(x)==0)throw new IOException("Short write");c.force(true);}}
 private void sync()throws IOException{try(FileChannel c=FileChannel.open(root,StandardOpenOption.READ)){c.force(true);}}
 private List<Path> records()throws IOException{ArrayList<Path> rows=new ArrayList<>();long total=0;try(DirectoryStream<Path> d=Files.newDirectoryStream(root)){for(Path p:d){if(Files.isSymbolicLink(p))throw new IOException("Symlink entry");String n=p.getFileName().toString();if(n.endsWith(".bin")||n.endsWith(".pending")){if(!Files.isRegularFile(p,LinkOption.NOFOLLOW_LINKS))throw new IOException("Store entry type");total+=Files.size(p);if(n.endsWith(".bin")){if(!n.matches("[0-9]{12}-[a-f0-9]{64}\\.bin"))throw new IOException("Record name");rows.add(p);}}}}if(rows.size()>MAX_RECORDS||total>MAX_TOTAL)throw new IOException("Existing store over quota");Collections.sort(rows);return rows;}
 private Snapshot decode(Path p)throws IOException{byte[] raw=read(p,MAX_BODY+512);String token=hash(raw);if(!p.getFileName().toString().endsWith("-"+token+".bin"))throw new IOException("Record digest");int[] ends=new int[6];int k=0;for(int i=0;i<raw.length&&k<6;i++)if(raw[i]==10)ends[k++]=i;if(k!=6)throw new IOException("Record header");String header=new String(raw,0,ends[5]+1,StandardCharsets.US_ASCII);String[] f=header.split("\n");if(f.length!=6||!f[0].equals("AERISWORKSPACE33")||!f[1].matches("[1-9][0-9]{0,11}")||!f[2].matches("ROOT|[a-f0-9]{64}")||!f[3].matches("[a-f0-9]{64}")||!f[4].matches("[1-9][0-9]{0,5}")||!f[5].equals("1"))throw new IOException("Record schema");byte[] body=Arrays.copyOfRange(raw,ends[5]+1,raw.length);long n=Long.parseLong(f[1]);if(!p.getFileName().toString().startsWith(String.format(Locale.ROOT,"%012d-",n))||body.length!=Integer.parseInt(f[4])||body.length>MAX_BODY||!hash(body).equals(f[3]))throw new IOException("Record body integrity");return new Snapshot(n,token,f[2],f[3],body);}
 public synchronized Snapshot load()throws IOException{List<Path> rows=records();Path head=safe("HEAD");if(!Files.exists(head,LinkOption.NOFOLLOW_LINKS))return null;String token=new String(read(head,65),StandardCharsets.US_ASCII);if(!token.matches("[a-f0-9]{64}\n"))throw new IOException("Head schema");token=token.trim();Map<String,Snapshot> all=new HashMap<>();for(Path p:rows){Snapshot s=decode(p);all.put(s.token,s);}Snapshot current=all.get(token);if(current==null)throw new IOException("Missing head record");HashSet<String> seen=new HashSet<>();Snapshot x=current;while(x!=null){if(!seen.add(x.token))throw new IOException("Revision cycle");if(x.previous.equals("ROOT"))break;Snapshot prev=all.get(x.previous);if(prev==null||prev.revision>=x.revision)throw new IOException("Revision chain");x=prev;}return current;}
 public synchronized Snapshot save(String expected,byte[] body)throws IOException{if(body==null||body.length==0||body.length>MAX_BODY||expected==null||!expected.matches("ROOT|[a-f0-9]{64}"))throw new IOException("Save bound/token");Path lock=safe("LOCK");try(FileChannel channel=FileChannel.open(lock,StandardOpenOption.CREATE,StandardOpenOption.WRITE,LinkOption.NOFOLLOW_LINKS)){FileLock lease;try{lease=channel.tryLock();}catch(OverlappingFileLockException e){throw new IOException("Writer busy",e);}if(lease==null)throw new IOException("Writer busy");try{Snapshot old=load();String actual=old==null?"ROOT":old.token;if(!actual.equals(expected))throw new IOException("Stale expected head");if(Files.exists(safe("HEAD.pending"),LinkOption.NOFOLLOW_LINKS))throw new IOException("Pending head: explicit recovery required");if(old!=null&&Arrays.equals(old.bytes,body))return old;List<Path> rows=records();long total=0,next=1;for(Path p:rows){Snapshot s=decode(p);next=Math.max(next,s.revision+1);total+=Files.size(p);}if(rows.size()>=MAX_RECORDS||total+body.length+512>MAX_TOTAL||root.toFile().getUsableSpace()<RESERVE+body.length+512)throw new IOException("Quota/reserve; no automatic deletion");if(next>999999999999L)throw new IOException("Revision bound");String header="AERISWORKSPACE33\n"+next+"\n"+actual+"\n"+hash(body)+"\n"+body.length+"\n1\n";ByteArrayOutputStream bytes=new ByteArrayOutputStream();bytes.write(header.getBytes(StandardCharsets.US_ASCII));bytes.write(body);byte[] raw=bytes.toByteArray();String token=hash(raw);Path file=safe(String.format(Locale.ROOT,"%012d-",next)+token+".bin");write(file,raw);sync();fault.at("RECORD_PUBLISHED");Path pending=safe("HEAD.pending");write(pending,(token+"\n").getBytes(StandardCharsets.US_ASCII));sync();fault.at("HEAD_PENDING");Files.move(pending,safe("HEAD"),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);sync();fault.at("HEAD_COMMITTED");return decode(file);}finally{lease.release();}}}
 public boolean pending()throws IOException{return Files.exists(safe("HEAD.pending"),LinkOption.NOFOLLOW_LINKS);}
}
